function chk(a) { if ((a >>> 0) >= MEM_SIZE) throw new Error('mem OOB @0x' + (a >>> 0).toString(16)); }
function LB(a){chk(a);return dv.getInt8(a);} 
function LBU(a){chk(a);return dv.getUint8(a);} 
function LH(a){chk(a);return dv.getInt16(a,true);} 
