  const acc = gf & 3;
  nf = (acc === 0) ? FSC.O_RDONLY : (acc === 1) ? FSC.O_WRONLY : FSC.O_RDWR;
  if (gf & 64)   nf |= FSC.O_CREAT;
  if (gf & 128)  nf |= FSC.O_EXCL;
  if (gf & 512)  nf |= FSC.O_TRUNC;
  if (gf & 1024) nf |= FSC.O_APPEND;
  return nf;
}

function sysOpen(pathAddr, flags, mode){
  const p = readCString(pathAddr);
  try {
    const fd = fs.openSync(p, transFlags(flags), (mode & 0o777) || 0o644);
    posMap.set(fd, (flags & 1024) ? fs.fstatSync(fd).size : 0);
    openPaths.set(fd, p);
    return fd;
  } catch (e) { return -errFromCode(e.code); }
}
function sysClose(fd){
  if (fd === 0 || fd === 1 || fd === 2) return 0;
  const p = openPaths.get(fd);
  try { fs.closeSync(fd); } catch (e) { return -errFromCode(e.code); }
  posMap.delete(fd); openPaths.delete(fd);
  if (p === '/tmp/frame.bmp') {
    framesSaved++;
    process.stderr.write('[vm] frame ' + framesSaved + ' saved -> /tmp/frame.bmp\n');
    if (framesSaved >= TARGET_FRAMES) { process.exit(0); }
  }
  return 0;
}
function sysRead(fd, bufAddr, count){
  if (count === 0) return 0;
  if (fd === 0) return 0; // stdin EOF
  try {
    const pos = posMap.get(fd) || 0;
    const n = fs.readSync(fd, guestBuf(bufAddr, count), 0, count, pos);
    posMap.set(fd, pos + n);
    return n;
  } catch (e) { return -errFromCode(e.code); }
}
function sysWrite(fd, bufAddr, count){
  if (count === 0) return 0;
  const view = guestBuf(bufAddr, count);
  try {
    if (fd === 1 || fd === 2) return fs.writeSync(fd, view);
    const pos = posMap.get(fd) || 0;
    const n = fs.writeSync(fd, view, 0, count, pos);
    posMap.set(fd, pos + n);
    return n;
  } catch (e) { return -errFromCode(e.code); }
}
function sysLseek(fd, offset, whence){
  if (!posMap.has(fd)) return -ERR.EBADF;
  let np;
  if (whence === 0) np = offset;
  else if (whence === 1) np = (posMap.get(fd) || 0) + offset;
  else if (whence === 2) { try { np = fs.fstatSync(fd).size + offset; } catch (e) { return -errFromCode(e.code); } }
  else return -ERR.EINVAL;
  if (np < 0) return -ERR.EINVAL;
  posMap.set(fd, np);
  return np;
}
function sysFsync(fd){ try { fs.fsyncSync(fd); return 0; } catch (e) { return -errFromCode(e.code); } }
function sysRename(a,b){ try { fs.renameSync(readCString(a), readCString(b)); return 0; } catch (e) { return -errFromCode(e.code); } }
function sysMkdir(a,mode){ try { fs.mkdirSync(readCString(a), (mode & 0o777) || 0o755); return 0; } catch (e) { return e.code==='EEXIST'?-ERR.EEXIST:-errFromCode(e.code); } }
function sysUnlink(a){ try { fs.unlinkSync(readCString(a)); return 0; } catch (e) { return -errFromCode(e.code); } }
function sysTime(ptr){ const t = Math.floor(Date.now() / 1000); if (ptr) SW(ptr, t); return t; }
function sysGettimeofday(tv, tz){ if (tv){ const ms = Date.now(); SW(tv, Math.floor(ms/1000)); SW(tv+4, (ms%1000)*1000); } return 0; }

function doSyscall(){
  const num = reg[2];
  const a0 = reg[4], a1 = reg[5], a2 = reg[6];
  let ret = 0;
  switch (num) {
    case 0:   ret = sysRead(a0, a1, a2 >>> 0); break;
    case 1:   ret = sysWrite(a0, a1, a2 >>> 0); break;
    case 2:   ret = sysOpen(a0, a1 | 0, a2 | 0); break;
    case 3:   ret = sysClose(a0); break;
    case 8:   ret = sysLseek(a0, a1 | 0, a2 | 0); break;
    case 74:  ret = sysFsync(a0); break;
    case 82:  ret = sysRename(a0, a1); break;
    case 83:  ret = sysMkdir(a0, a1 | 0); break;
    case 87:  ret = sysUnlink(a0); break;
    case 60:  process.exit(a0 | 0); break;
    case 96:  ret = sysGettimeofday(a0, a1); break;
    case 201: ret = sysTime(a0); break;
    case 35:  ret = 0; break; // nanosleep
    default:  ret = -ERR.ENOSYS;
  }
  reg[2] = ret | 0;
}

// ---------------------------------------------------------------------------
// Execution
// ---------------------------------------------------------------------------
let entry = loadElf(ELF_PATH);
reg[29] = STACK_TOP;          // $sp
reg[28] = 0x0047d090;         // $gp (reginfo ri_gp_value)
reg[31] = 0;                  // $ra

let pc = entry >>> 0;
let npc = (pc + 4) >>> 0;
const startWall = Date.now();
let icount = 0;

function run(){
  while (true) {
    const inst = i32[pc >>> 2] | 0;
    // advance; delay-slot instruction is fetched next iteration
    pc = npc;
    npc = (pc + 4) >>> 0;

    if ((++icount & 0x3ffffff) === 0) {
      if (Date.now() - startWall > WALL_LIMIT_MS) {
        process.stderr.write('[vm] wall-clock limit reached after ' + icount + ' insns\n');
        process.exit(2);
      }
    }

    const op = inst >>> 26;
    const rs = (inst >>> 21) & 31;
    const rt = (inst >>> 16) & 31;
    const rd = (inst >>> 11) & 31;
    const sa = (inst >>> 6) & 31;
    const funct = inst & 63;
    const imm = inst & 0xffff;
    const simm = (imm << 16) >> 16;

    switch (op) {
      case 0x00: { // SPECIAL
        switch (funct) {
          case 0x00: reg[rd] = reg[rt] << sa; break;                 // sll
          case 0x02: // srl / rotr
            if ((inst >>> 21) & 1) reg[rd] = sa ? ((reg[rt] >>> sa) | (reg[rt] << (32 - sa))) : reg[rt];
            else reg[rd] = reg[rt] >>> sa; break;
          case 0x03: reg[rd] = reg[rt] >> sa; break;                 // sra
          case 0x04: reg[rd] = reg[rt] << (reg[rs] & 31); break;     // sllv
          case 0x06: { const s = reg[rs] & 31;                       // srlv / rotrv
            if ((inst >>> 6) & 1) reg[rd] = s ? ((reg[rt] >>> s) | (reg[rt] << (32 - s))) : reg[rt];
            else reg[rd] = reg[rt] >>> s; break; }
          case 0x07: reg[rd] = reg[rt] >> (reg[rs] & 31); break;     // srav
          case 0x08: npc = reg[rs] >>> 0; break;                     // jr
          case 0x09: reg[rd] = (pc + 4) | 0; npc = reg[rs] >>> 0; break; // jalr (link=cur+8=pc+4)
          case 0x0a: if (reg[rt] === 0) reg[rd] = reg[rs]; break;    // movz
          case 0x0b: if (reg[rt] !== 0) reg[rd] = reg[rs]; break;    // movn
          case 0x0c: doSyscall(); break;                            // syscall
          case 0x0d: throw new Error('break @0x' + ((pc - 4) >>> 0).toString(16)); // break
          case 0x0f: break;                                         // sync
          case 0x10: reg[rd] = HI; break;                           // mfhi
          case 0x11: HI = reg[rs]; break;                           // mthi
          case 0x12: reg[rd] = LO; break;                           // mflo
          case 0x13: LO = reg[rs]; break;                           // mtlo
          case 0x18: { const p = BigInt(reg[rs]) * BigInt(reg[rt]); // mult
            LO = Number(p & 0xffffffffn) | 0; HI = Number((p >> 32n) & 0xffffffffn) | 0; break; }
          case 0x19: { const p = BigInt(reg[rs] >>> 0) * BigInt(reg[rt] >>> 0); // multu
            LO = Number(p & 0xffffffffn) | 0; HI = Number((p >> 32n) & 0xffffffffn) | 0; break; }
          case 0x1a: { const a = reg[rs], b = reg[rt]; if (b !== 0) { LO = (a / b) | 0; HI = (a % b) | 0; } break; } // div
          case 0x1b: { const a = reg[rs] >>> 0, b = reg[rt] >>> 0; if (b !== 0) { LO = (a / b) >>> 0; HI = (a % b) >>> 0; } break; } // divu
          case 0x20: reg[rd] = (reg[rs] + reg[rt]) | 0; break;       // add
          case 0x21: reg[rd] = (reg[rs] + reg[rt]) | 0; break;      // addu
          case 0x22: reg[rd] = (reg[rs] - reg[rt]) | 0; break;      // sub
          case 0x23: reg[rd] = (reg[rs] - reg[rt]) | 0; break;      // subu
          case 0x24: reg[rd] = reg[rs] & reg[rt]; break;            // and
          case 0x25: reg[rd] = reg[rs] | reg[rt]; break;            // or
          case 0x26: reg[rd] = reg[rs] ^ reg[rt]; break;            // xor
          case 0x27: reg[rd] = ~(reg[rs] | reg[rt]); break;         // nor
          case 0x2a: reg[rd] = (reg[rs] < reg[rt]) ? 1 : 0; break;  // slt
          case 0x2b: reg[rd] = ((reg[rs] >>> 0) < (reg[rt] >>> 0)) ? 1 : 0; break; // sltu
          case 0x30: if (reg[rs] >= reg[rt]) throw new Error('tge trap'); break; // tge
          case 0x34: if (reg[rs] === reg[rt]) { /* teq: divide-by-zero guard; ignore */ } break; // teq
          case 0x36: if (reg[rs] !== reg[rt]) throw new Error('tne trap'); break; // tne
          default: throw new Error('unhandled SPECIAL funct 0x' + funct.toString(16) + ' @0x' + ((pc - 4) >>> 0).toString(16));
        }
        break;
      }
      case 0x01: { // REGIMM
        switch (rt) {
          case 0x00: if (reg[rs] < 0) npc = (pc + (simm << 2)) >>> 0; break;   // bltz
          case 0x01: if (reg[rs] >= 0) npc = (pc + (simm << 2)) >>> 0; break;  // bgez
          case 0x02: if (reg[rs] < 0) npc = (pc + (simm << 2)) >>> 0; break;   // bltzl (no likely-null: exec slot)
          case 0x03: if (reg[rs] >= 0) npc = (pc + (simm << 2)) >>> 0; break;  // bgezl
          case 0x10: reg[31] = (pc + 4) | 0; if (reg[rs] < 0) npc = (pc + (simm << 2)) >>> 0; break;  // bltzal
          case 0x11: reg[31] = (pc + 4) | 0; if (reg[rs] >= 0) npc = (pc + (simm << 2)) >>> 0; break; // bgezal
          default: throw new Error('unhandled REGIMM rt 0x' + rt.toString(16) + ' @0x' + ((pc - 4) >>> 0).toString(16));
        }
        break;
      }
      case 0x02: npc = ((pc & 0xf0000000) | ((inst & 0x3ffffff) << 2)) >>> 0; break; // j
      case 0x03: reg[31] = (pc + 4) | 0; npc = ((pc & 0xf0000000) | ((inst & 0x3ffffff) << 2)) >>> 0; break; // jal
      case 0x04: if (reg[rs] === reg[rt]) npc = (pc + (simm << 2)) >>> 0; break; // beq
      case 0x05: if (reg[rs] !== reg[rt]) npc = (pc + (simm << 2)) >>> 0; break; // bne
      case 0x06: if (reg[rs] <= 0) npc = (pc + (simm << 2)) >>> 0; break;        // blez
      case 0x07: if (reg[rs] > 0) npc = (pc + (simm << 2)) >>> 0; break;         // bgtz
      case 0x08: reg[rt] = (reg[rs] + simm) | 0; break;   // addi (no trap)
      case 0x09: reg[rt] = (reg[rs] + simm) | 0; break;   // addiu
      case 0x0a: reg[rt] = (reg[rs] < simm) ? 1 : 0; break; // slti
      case 0x0b: reg[rt] = ((reg[rs] >>> 0) < (simm >>> 0)) ? 1 : 0; break; // sltiu
      case 0x0c: reg[rt] = reg[rs] & imm; break;          // andi
      case 0x0d: reg[rt] = reg[rs] | imm; break;          // ori
      case 0x0e: reg[rt] = reg[rs] ^ imm; break;          // xori
      case 0x0f: reg[rt] = imm << 16; break;              // lui
      case 0x11: execCop1(inst, rs, rt, rd, sa, funct); break; // COP1
      case 0x1c: { // SPECIAL2
        if (funct === 0x02) reg[rd] = Math.imul(reg[rs], reg[rt]);        // mul
        else if (funct === 0x00) { const p = BigInt(reg[rs]) * BigInt(reg[rt]) + (BigInt(HI >>> 0) << 32n) + BigInt(LO >>> 0); LO = Number(p & 0xffffffffn) | 0; HI = Number((p >> 32n) & 0xffffffffn) | 0; } // madd
        else if (funct === 0x20) { let x = reg[rs] >>> 0, n = 0; while (n < 32 && !(x & 0x80000000)) { n++; x <<= 1; } reg[rd] = n; } // clz
        else throw new Error('unhandled SPECIAL2 funct 0x' + funct.toString(16));
        break;
      }
      case 0x1f: { // SPECIAL3
        if (funct === 0x00) { const size = rd + 1; const pos = sa;         // ext
          reg[rt] = (size >= 32) ? (reg[rs] >>> pos) : ((reg[rs] >>> pos) & ((1 << size) - 1)); }
        else if (funct === 0x04) { const pos = sa, msb = rd, size = msb - pos + 1; // ins
          const mask = (size >= 32) ? 0xffffffff : ((1 << size) - 1);
          reg[rt] = ((reg[rt] & ~(mask << pos)) | ((reg[rs] & mask) << pos)) | 0; }
        else if (funct === 0x20) { // BSHFL
          if (sa === 0x02) { const v = reg[rt] >>> 0; reg[rd] = (((v & 0x00ff00ff) << 8) | ((v >>> 8) & 0x00ff00ff)) | 0; } // wsbh
          else if (sa === 0x10) reg[rd] = (reg[rt] << 24) >> 24; // seb
          else if (sa === 0x18) reg[rd] = (reg[rt] << 16) >> 16; // seh
          else throw new Error('unhandled BSHFL sa 0x' + sa.toString(16)); }
        else if (funct === 0x3b) { reg[rt] = 0; } // rdhwr (return 0)
        else throw new Error('unhandled SPECIAL3 funct 0x' + funct.toString(16));
        break;
      }
      case 0x20: reg[rt] = LB((reg[rs] + simm) | 0); break;   // lb
      case 0x21: reg[rt] = LH((reg[rs] + simm) | 0); break;   // lh
      case 0x22: { // lwl
        const addr = (reg[rs] + simm) | 0; const b = addr & 3; const w = LW(addr & ~3);
        const shift = 24 - 8 * b; const keep = shift ? ((1 << shift) - 1) : 0;
        reg[rt] = ((w << shift) | (reg[rt] & keep)) | 0; break; }
      case 0x23: reg[rt] = LW((reg[rs] + simm) | 0); break;   // lw
      case 0x24: reg[rt] = LBU((reg[rs] + simm) | 0); break;  // lbu
      case 0x25: reg[rt] = LHU((reg[rs] + simm) | 0); break;  // lhu
      case 0x26: { // lwr
        const addr = (reg[rs] + simm) | 0; const b = addr & 3; const w = LW(addr & ~3);
        const shift = 8 * b; const nl = w >>> shift;
        const mask = b === 0 ? 0 : ((0xffffffff << (8 * (4 - b))) >>> 0);
        reg[rt] = ((reg[rt] & mask) | nl) | 0; break; }
      case 0x28: SB((reg[rs] + simm) | 0, reg[rt]); break;    // sb
      case 0x29: SH((reg[rs] + simm) | 0, reg[rt]); break;    // sh
      case 0x2a: { // swl
        const addr = (reg[rs] + simm) | 0; const b = addr & 3; const al = addr & ~3; const w = LW(al);
        const shift = 24 - 8 * b; const low = ((b + 1) >= 4) ? 0xffffffff : ((1 << (8 * (b + 1))) - 1);
        SW(al, ((w & ~low) | ((reg[rt] >>> shift) & low)) | 0); break; }
      case 0x2b: SW((reg[rs] + simm) | 0, reg[rt]); break;    // sw
      case 0x2e: { // swr
        const addr = (reg[rs] + simm) | 0; const b = addr & 3; const al = addr & ~3; const w = LW(al);
        const shift = 8 * b; const keep = b === 0 ? 0 : ((1 << (8 * b)) - 1);
        SW(al, ((w & keep) | ((reg[rt] << shift) & ~keep)) | 0); break; }
      case 0x31: fpr[rt] = LW((reg[rs] + simm) | 0) >>> 0; break; // lwc1
      case 0x35: { const a = (reg[rs] + simm) | 0; fpr[rt & ~1] = LW(a) >>> 0; fpr[(rt & ~1) | 1] = LW(a + 4) >>> 0; break; } // ldc1
      case 0x39: SW((reg[rs] + simm) | 0, fpr[rt] | 0); break; // swc1
      case 0x3d: { const a = (reg[rs] + simm) | 0; SW(a, fpr[rt & ~1] | 0); SW(a + 4, fpr[(rt & ~1) | 1] | 0); break; } // sdc1
      case 0x2f: break; // pref
      case 0x33: break; // pref
      default:
        throw new Error('unhandled opcode 0x' + op.toString(16) + ' inst 0x' + (inst >>> 0).toString(16) + ' @0x' + ((pc - 4) >>> 0).toString(16));
    }
    reg[0] = 0;
  }
}

function execCop1(inst, rs, rt, rd, sa, funct){
  if (rs === 0x08) { // BC1
    const tf = (inst >>> 16) & 1; const cc = (inst >>> 18) & 7;
    if (fcc[cc] === tf) npc = (pc + (((inst & 0xffff) << 16 >> 16) << 2)) >>> 0;
    return;
  }
  switch (rs) {
    case 0x00: reg[rt] = fpr[rd] | 0; return;       // mfc1  (fs=rd)
    case 0x02: reg[rt] = 0; return;                 // cfc1
    case 0x03: reg[rt] = fpr[(rd & ~1) | 1] | 0; return; // mfhc1
    case 0x04: fpr[rd] = reg[rt] >>> 0; return;     // mtc1
    case 0x06: return;                              // ctc1 (ignore)
    case 0x07: fpr[(rd & ~1) | 1] = reg[rt] >>> 0; return; // mthc1
  }
  // formatted op: rs = fmt (0x10=S,0x11=D,0x14=W,0x15=L)
  const fmt = rs, ft = rt, fs = rd, fd = sa;
  if (funct >= 0x30) { // c.cond.fmt
    const cc = (inst >>> 8) & 7;
    const a = fGet(fmt, fs), b = fGet(fmt, ft);
    const un = (a !== a) || (b !== b);
    const less = !un && a < b;
    const eq = !un && a === b;
    const pred = (un && (funct & 1)) || (eq && ((funct >> 1) & 1)) || (less && ((funct >> 2) & 1));
    fcc[cc] = pred ? 1 : 0;
    return;
  }
  switch (funct) {
    case 0x00: fSet(fmt, fd, fGet(fmt, fs) + fGet(fmt, ft)); return; // add
    case 0x01: fSet(fmt, fd, fGet(fmt, fs) - fGet(fmt, ft)); return; // sub
    case 0x02: fSet(fmt, fd, fGet(fmt, fs) * fGet(fmt, ft)); return; // mul
    case 0x03: fSet(fmt, fd, fGet(fmt, fs) / fGet(fmt, ft)); return; // div
    case 0x04: fSet(fmt, fd, Math.sqrt(fGet(fmt, fs))); return;      // sqrt
    case 0x05: fSet(fmt, fd, Math.abs(fGet(fmt, fs))); return;       // abs
    case 0x06: fSet(fmt, fd, fGet(fmt, fs)); return;                 // mov
    case 0x07: fSet(fmt, fd, -fGet(fmt, fs)); return;                // neg
    case 0x08: fSet(fmt, fd, Math.round(fGet(fmt, fs))); return;     // round.l (approx)
    case 0x09: fSet(fmt, fd, Math.trunc(fGet(fmt, fs))); return;     // trunc.l
    case 0x0c: { const v = fGet(fmt, fs); fpr[fd] = (Math.round(v) | 0) >>> 0; return; } // round.w
    case 0x0d: { const v = fGet(fmt, fs); fpr[fd] = (Math.trunc(v) | 0) >>> 0; return; } // trunc.w
    case 0x0e: { const v = fGet(fmt, fs); fpr[fd] = (Math.ceil(v) | 0) >>> 0; return; }  // ceil.w
    case 0x0f: { const v = fGet(fmt, fs); fpr[fd] = (Math.floor(v) | 0) >>> 0; return; } // floor.w
    case 0x11: { const tf = (inst >>> 16) & 1; const cc = (inst >>> 18) & 7; if (fcc[cc] === tf) fSet(fmt, fd, fGet(fmt, fs)); return; } // movt/movf
    case 0x20: fSetS(fd, fGet(fmt, fs)); return; // cvt.s
    case 0x21: fSetD(fd, fGet(fmt, fs)); return; // cvt.d
    case 0x24: { const v = fGet(fmt, fs); fpr[fd] = (Math.round(v) | 0) >>> 0; return; } // cvt.w
    default: throw new Error('unhandled COP1 funct 0x' + funct.toString(16) + ' fmt 0x' + fmt.toString(16));
  }
}

try {
  run();
} catch (e) {
  process.stderr.write('[vm] fatal: ' + (e && e.stack ? e.stack : e) + '\n');
  process.stderr.write('[vm] icount=' + icount + ' pc=0x' + ((pc - 4) >>> 0).toString(16) + '\n');
  process.exit(1);
}
